select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-so-151","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For volatile component A in an ideal liquid mixture, Raoult’s relation is written","options":["$p_A = p_A^\\circ x_A$","$p_A = p_A^\\circ / x_A$","$p_A = p_A^\\circ + x_A$","$p_A = K_H x_A$"],"answer_index":0,"explanation":"Partial pressure equals the pure-liquid vapour pressure times the liquid mole fraction.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-152","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Total vapour pressure over an ideal binary liquid equals","options":["$p_A^\\circ x_A + p_B^\\circ x_B$","$p_A^\\circ + p_B^\\circ$","$x_A + x_B$","$K_H(x_A + x_B)$"],"answer_index":0,"explanation":"Each component contributes independently: $p_{\\mathrm{total}} = \\sum p_i^\\circ x_i$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-153","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dissolving a non-volatile solute in a pure solvent","options":["lowers the solvent vapour pressure","raises the solvent vapour pressure","leaves the vapour pressure unchanged","always doubles the vapour pressure"],"answer_index":0,"explanation":"Solvent mole fraction falls below 1, so $p = p^\\circ x_{\\mathrm{solvent}} < p^\\circ$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-154","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Vapour in equilibrium with an ideal A–B liquid is richer in the component that has the","options":["higher pure-liquid vapour pressure","lower pure-liquid vapour pressure","larger molar mass only","zero Henry constant"],"answer_index":0,"explanation":"The more volatile liquid (larger $p^\\circ$) contributes a larger partial pressure, so $y > x$ for that component.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-155","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A graph of total vapour pressure against liquid mole fraction for an ideal binary pair is","options":["the straight line joining $p_A^\\circ$ and $p_B^\\circ$","a curve with a maximum","a curve with a minimum","a parabola through the origin"],"answer_index":0,"explanation":"Ideal $p_{\\mathrm{total}}$ varies linearly between the two pure-liquid vapour pressures.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-156","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dalton’s law applied to the vapour above a solution gives the vapour mole fraction of A as","options":["$y_A = p_A / p_{\\mathrm{total}}$","$y_A = x_A$","$y_A = p_A^\\circ$","$y_A = 1 - p_A$"],"answer_index":0,"explanation":"Each partial pressure is that component’s mole fraction in the gas times the total pressure.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-157","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Raoult’s law for the solvent becomes exact in the limit of a solution that is","options":["very dilute in solute","very concentrated in solute","frozen solid","an emulsion"],"answer_index":0,"explanation":"The solvent then has $x \\approx 1$ and behaves as a nearly pure liquid obeying Raoult’s law.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-158","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A closed flask of pure liquid A at equilibrium exerts","options":["its saturation vapour pressure $p_A^\\circ$","zero pressure","only $K_H$","osmotic pressure"],"answer_index":0,"explanation":"The equilibrium vapour pressure of the pure liquid is the $p^\\circ$ used in Raoult’s law.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-159","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"When the liquid is pure A ($x_A = 1$), Raoult’s law reduces to","options":["$p_A = p_A^\\circ$","$p_A = 0$","$p_A = K_H$","$p_A = \\pi$"],"answer_index":0,"explanation":"The partial pressure of a pure liquid is just its own vapour pressure.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-160","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two liquids that obey Raoult’s law at every composition are said to form","options":["an ideal solution","an azeotrope in every case","a colloid","a suspension"],"answer_index":0,"explanation":"Ideal solutions follow $p_i = p_i^\\circ x_i$ over the whole composition range.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-161","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A clear drop in vapour pressure is used as a colligative effect when the added solute is","options":["non-volatile (or far less volatile than the solvent)","more volatile than the solvent","a catalyst","always a noble gas"],"answer_index":0,"explanation":"Only then does the total pressure fall below $p^\\circ$ of the pure solvent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-162","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For an ideal mix the vapour mole fraction of A is related to the liquid composition by","options":["$y_A = (p_A^\\circ x_A) / p_{\\mathrm{total}}$","$y_A = x_A$","$y_A = p_A^\\circ$","$y_A = K_H x_A$"],"answer_index":0,"explanation":"Combine Raoult ($p_A = p_A^\\circ x_A$) with Dalton ($y_A = p_A / p_{\\mathrm{total}}$).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-163","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At a given temperature, the liquid with the larger $p^\\circ$ is described as","options":["more volatile","less volatile","non-volatile","ideal only"],"answer_index":0,"explanation":"Volatility tracks the equilibrium vapour pressure of the pure liquid.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-164","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Pure toluene has vapour pressure 30 torr. In an ideal mix with $x_{\\mathrm{toluene}} = 0.40$, the partial pressure of toluene is","options":["12 torr","30 torr","18 torr","70 torr"],"answer_index":0,"explanation":"$p = p^\\circ x = 30 \\times 0.40 = 12$ torr.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-165","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"An ideal pair has $p_A^\\circ = 80$ mm Hg and $p_B^\\circ = 20$ mm Hg. At $x_A = 0.50$ the total pressure is","options":["50 mm Hg","100 mm Hg","80 mm Hg","20 mm Hg"],"answer_index":0,"explanation":"$p = 80 \\times 0.50 + 20 \\times 0.50 = 50$ mm Hg.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-166","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Benzene ($p^\\circ = 75$ torr) plus a non-volatile solute form a liquid with $x_{\\mathrm{benzene}} = 0.90$. The vapour pressure of that solution is","options":["67.5 torr","75 torr","7.5 torr","83 torr"],"answer_index":0,"explanation":"Only benzene contributes: $p = 75 \\times 0.90 = 67.5$ torr.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-167","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Above an ideal liquid the partial pressure of A is 24 kPa while the total pressure is 60 kPa. The vapour mole fraction of A is","options":["0.40","0.24","0.60","1.0"],"answer_index":0,"explanation":"$y_A = p_A / p_{\\mathrm{total}} = 24/60 = 0.40$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-168","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Component B is non-volatile. If $x_{\\mathrm{solvent}} = 0.95$ and $p^\\circ_{\\mathrm{solvent}} = 20$ kPa, the solution vapour pressure equals","options":["19 kPa","20 kPa","1 kPa","21 kPa"],"answer_index":0,"explanation":"$p = 20 \\times 0.95 = 19$ kPa.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-169","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two ideal liquids are present in equal mole fractions. $p_A^\\circ = 90$ torr and $p_B^\\circ = 60$ torr. Total vapour pressure is","options":["75 torr","150 torr","90 torr","30 torr"],"answer_index":0,"explanation":"$p = 0.50 \\times 90 + 0.50 \\times 60 = 75$ torr.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-170","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Vapour over an ideal mix is analysed as $y_A = 0.70$ when $p_{\\mathrm{total}} = 100$ torr. Partial pressure of A in that vapour is","options":["70 torr","30 torr","100 torr","0.70 torr"],"answer_index":0,"explanation":"$p_A = y_A p_{\\mathrm{total}} = 0.70 \\times 100 = 70$ torr.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-171","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"An ideal blend has $x_A = 0.30$, $p_A^\\circ = 200$ torr and $p_B^\\circ = 100$ torr. Mole fraction of A in the vapour is nearest","options":["0.46","0.30","0.67","0.23"],"answer_index":0,"explanation":"$p_A = 60$ torr, $p_B = 70$ torr, $p = 130$ torr, so $y_A = 60/130 \\approx 0.46$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-172","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At 350 K the liquid mole fraction of hexane is 0.25 ($p^\\circ_{\\mathrm{hex}} = 90$ kPa, $p^\\circ_{\\mathrm{hept}} = 30$ kPa). Total vapour pressure of this ideal pair is","options":["45 kPa","60 kPa","30 kPa","120 kPa"],"answer_index":0,"explanation":"$p = 90 \\times 0.25 + 30 \\times 0.75 = 22.5 + 22.5 = 45$ kPa.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-173","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"An ideal liquid solution is characterised by","options":["$\\Delta H_{\\mathrm{mix}} = 0$ and $\\Delta V_{\\mathrm{mix}} = 0$","$\\Delta H_{\\mathrm{mix}} > 0$ only","$\\Delta G_{\\mathrm{mix}} = 0$","$\\Delta S_{\\mathrm{mix}} = 0$"],"answer_index":0,"explanation":"No heat is absorbed or evolved and the volumes are strictly additive for an ideal mix.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-174","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Molecular interactions in an ideal A–B solution satisfy","options":["A–A, B–B and A–B forces of similar strength","A–B much stronger than like pairs","A–B much weaker than like pairs","no A–B contacts at all"],"answer_index":0,"explanation":"Equal interaction energies make the mixture obey Raoult’s law at all compositions.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-175","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Benzene and toluene form a nearly ideal pair because they have","options":["similar size and intermolecular forces","opposite polarity","hydrogen bonds of very different strength","ionic lattices"],"answer_index":0,"explanation":"Both are non-polar aromatics of comparable size, so A–B forces match A–A and B–B.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
